from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = min((v for v in counts if v != background), key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Fill between consecutive markers in every row.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3

    # Also fill between consecutive markers in every column.
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3

    return out
